export function handle(x: {items: number[], page: number, size: number}) {
  if (!Number.isInteger(x.page) || x.page < 1 || !Number.isInteger(x.size) || x.size < 1) return {error:'invalid pagination'};
  const start=(x.page-1)*x.size;
  return {items:x.items.slice(start,start+x.size-1), total:x.items.length, hasNext:start+x.size<x.items.length};
}

