def select(request):
    offset=timezone(timedelta(minutes=request['offset_minutes']))
    selected=[]
    for row in request['rows']:
        instant=datetime.fromisoformat(row['at'].replace('Z','+00:00'))
        if instant.astimezone(timezone.utc).date().isoformat()==request['day']:
            selected.append(row['id'])
    return selected

